        try {
            if (status === 'verified') {
                const addCreditsResult = await this.addCreditsUseCase.execute(userId, creditsToGrant);
                if (addCreditsResult.isFailure) {
                    return Result.fail(BillingError.internal(addCreditsResult.error?.message));
