                    status: 'verified',
                    adminNotes: adminNotes || 'Payment approved.',
                    verifiedAt: new Date().toISOString(),
                    verifiedBy: adminId
                });

                if (updateResult.isFailure) return updateResult as any;

                await this.notificationService.send(userId, {
                    title: "Payment Approved",
                    description: `Your purchase of ${creditsToGrant} credits has been approved.`,
                    icon: "credit-card",
                    link: '/payment-history'
                });
            } else {
                const updateResult = await this.transactionRepository.update(transactionId, {
                    status: 'rejected',
                    adminNotes: adminNotes || 'Payment could not be verified.',
                    verifiedAt: new Date().toISOString(),
                    verifiedBy: adminId
                });

                if (updateResult.isFailure) return updateResult as any;

                await this.notificationService.send(userId, {
                    title: "Payment Rejected",
                    description: `Your recent purchase could not be verified. Please contact support.`,
                    icon: "credit-card",
                    link: '/payment-history'
                });
            }
            return Result.ok();
        } catch (error: any) {
            return Result.fail(BillingError.internal(error.message));
        }
    }
}

import { TransactionProperties } from "../../domain/entities/Transaction";
import { Result } from "@/lib/utils/result";
import { BillingError } from "../../domain/errors/BillingErrors";

@injectable()
export class SubmitPaymentRequestUseCase {
    constructor(
        @inject(ITransactionRepositoryToken)
        private transactionRepository: ITransactionRepository,
        @inject(IFileStorageServiceToken)
        private fileStorageService: IFileStorageService,
        @inject(IUserRepositoryToken)
        private userRepository: IUserRepository,
        @inject(INotificationServiceToken)
        private notificationService: INotificationService
    ) {}

    async execute(params: { 
        file: Buffer, 
        fileName: string, 
        contentType: string, 
        userId: string, 
        planId: string, 
        planName: string, 
        credits: number, 
        price: number, 
        userName: string, 
        userEmail: string 
    }): Promise<Result<TransactionProperties, BillingError>> {
        const { file, fileName, contentType, userId, ...rest } = params;

        try {
            // 1. Upload proof file
            const storagePath = `payment_proofs/${userId}/${Date.now()}-${fileName}`;
            const fileUrl = await this.fileStorageService.upload(storagePath, file, contentType);

            // 2. Create transaction record
            const result = await this.transactionRepository.save({
                userId,
                ...rest,
                status: 'pending',
                proofUrl: fileUrl,
                createdAt: new Date().toISOString()
            } as any);

            if (result.isFailure) return result;
            const transaction = result.getValue();

            // 3. Notify all admins
            const adminsResult = await this.userRepository.getAdmins();
            if (adminsResult.isSuccess) {
                const admins = adminsResult.getValue();
                const notificationPayload = {
                    title: "New Payment Request",
                    description: `User ${params.userName || params.userEmail} submitted a payment request for $${params.price}.`,
                    icon: "credit-card",
                    link: '/admin/manage-payments'
                };

                await Promise.all(admins.map(admin => this.notificationService.send(admin.id, notificationPayload)));
            }

            return Result.ok(transaction);
        } catch (error: any) {
            return Result.fail(BillingError.internal(error.message));
        }
    }
}

